// Generates native/src/icons.rs from the website's own Font Awesome Free solid icons, so the native app draws
// exactly the glyphs the web app does. Run from the repository root after changing the list:
//   node native/scripts/generate-icons.mjs
// This is an asset-build step only: the generated file is checked in and the app needs no Node at runtime.
import { readFileSync, writeFileSync, copyFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const require = createRequire(join(root, "package.json"));
const icons = require("@fortawesome/free-solid-svg-icons");
const pkg = JSON.parse(readFileSync(join(root, "node_modules/@fortawesome/free-solid-svg-icons/package.json"), "utf8"));

// Rust constant name -> Font Awesome export used by the web app.
const wanted = {
  BOOK_OPEN: "faBookOpen", // primary nav: Browse
  PENCIL: "faPencil", // primary nav: Journal
  SHOE_PRINTS: "faShoePrints", // primary nav: Come Follow Me
  GEAR: "faGear", // nav settings and reader settings
  CHEVRON_LEFT: "faChevronLeft", // nav collapse toggle
  MAGNIFYING_GLASS: "faMagnifyingGlass", // reader search
  BOOK: "faBook", // Log
  EYE: "faEye", // simple mode off
  EYE_SLASH: "faEyeSlash", // simple mode on / exit
  XMARK: "faXmark",
  COPY: "faCopy",
  HIGHLIGHTER: "faHighlighter",
  BOOKMARK: "faBookmark",
  NOTE_STICKY: "faNoteSticky",
  CHECK: "faCheck",
};

let out = `// @generated by native/scripts/generate-icons.mjs from @fortawesome/free-solid-svg-icons ${pkg.version}.
// Font Awesome Free icons are licensed CC BY 4.0; see native/assets/licenses/FontAwesome-Free-LICENSE.txt.

pub struct Icon {
    pub width: u32,
    pub height: u32,
    pub path: &'static str,
}
`;
for (const [name, exportName] of Object.entries(wanted)) {
  const definition = icons[exportName];
  if (!definition) throw new Error(`Unknown Font Awesome icon ${exportName}`);
  const [width, height, , , path] = definition.icon;
  if (typeof path !== "string") throw new Error(`${exportName} is a duotone or multi-path icon`);
  out += `pub const ${name}: Icon = Icon {\n    width: ${width},\n    height: ${height},\n    path: ${JSON.stringify(path)},\n};\n`;
}
writeFileSync(join(root, "native/src/icons.rs"), out);
copyFileSync(
  join(root, "node_modules/@fortawesome/free-solid-svg-icons/LICENSE.txt"),
  join(root, "native/assets/licenses/FontAwesome-Free-LICENSE.txt")
);
console.log(`Wrote ${Object.keys(wanted).length} icons from Font Awesome ${pkg.version}`);
